BEGIN TRANSACTION;
CREATE TABLE "contracts" ("contract_id" TEXT, "supplier_id" TEXT, "contract_type" TEXT, "start_date" TEXT, "end_date" TEXT, "contract_value" INTEGER, "payment_terms" TEXT, "status" TEXT, PRIMARY KEY ("contract_id"), FOREIGN KEY ("supplier_id") REFERENCES "suppliers" ("supplier_id"));
CREATE TABLE "delivery_events" ("delivery_event_id" TEXT, "shipment_id" TEXT, "event_type" TEXT, "event_date" TEXT, "location" TEXT, "remarks" TEXT, PRIMARY KEY ("delivery_event_id"), FOREIGN KEY ("shipment_id") REFERENCES "shipments" ("shipment_id"));
CREATE TABLE "inspections" ("inspection_id" TEXT, "shipment_id" TEXT, "supplier_id" TEXT, "inspection_date" TEXT, "inspection_type" TEXT, "inspected_quantity" INTEGER, "defective_quantity" INTEGER, "defect_rate" REAL, "quality_status" TEXT, PRIMARY KEY ("inspection_id"), FOREIGN KEY ("shipment_id") REFERENCES "shipments" ("shipment_id"), FOREIGN KEY ("supplier_id") REFERENCES "suppliers" ("supplier_id"));
CREATE TABLE "invoices" ("invoice_id" TEXT, "purchase_order_id" TEXT, "supplier_id" TEXT, "invoice_date" TEXT, "invoice_amount" REAL, "payment_status" TEXT, PRIMARY KEY ("invoice_id"), FOREIGN KEY ("purchase_order_id") REFERENCES "purchase_orders" ("purchase_order_id"), FOREIGN KEY ("supplier_id") REFERENCES "suppliers" ("supplier_id"));
CREATE TABLE "po_lines" ("po_line_id" TEXT, "purchase_order_id" TEXT, "product_name" TEXT, "quantity" INTEGER, "unit_price" INTEGER, "line_total" INTEGER, PRIMARY KEY ("po_line_id"), FOREIGN KEY ("purchase_order_id") REFERENCES "purchase_orders" ("purchase_order_id"));
CREATE TABLE "purchase_orders" ("purchase_order_id" TEXT, "supplier_id" TEXT, "contract_id" TEXT, "order_date" TEXT, "expected_delivery_date" TEXT, "total_amount" INTEGER, "status" TEXT, PRIMARY KEY ("purchase_order_id"), FOREIGN KEY ("supplier_id") REFERENCES "suppliers" ("supplier_id"), FOREIGN KEY ("contract_id") REFERENCES "contracts" ("contract_id"));
CREATE TABLE "risk_signals" ("risk_signal_id" TEXT, "supplier_id" TEXT, "risk_type" TEXT, "severity" TEXT, "description" TEXT, "status" TEXT, PRIMARY KEY ("risk_signal_id"), FOREIGN KEY ("supplier_id") REFERENCES "suppliers" ("supplier_id"));
CREATE TABLE "shipments" ("shipment_id" TEXT, "purchase_order_id" TEXT, "supplier_id" TEXT, "shipment_date" TEXT, "expected_delivery_date" TEXT, "carrier" TEXT, "tracking_number" TEXT, "status" TEXT, PRIMARY KEY ("shipment_id"), FOREIGN KEY ("purchase_order_id") REFERENCES "purchase_orders" ("purchase_order_id"), FOREIGN KEY ("supplier_id") REFERENCES "suppliers" ("supplier_id"));
CREATE TABLE "sites" ("site_id" TEXT, "supplier_id" TEXT, "city" TEXT, "site_type" TEXT, PRIMARY KEY ("site_id"), FOREIGN KEY ("supplier_id") REFERENCES "suppliers" ("supplier_id"));
CREATE TABLE "supplier_scores" ("supplier_score_id" TEXT, "supplier_id" TEXT, "delivery_score" REAL, "quality_score" REAL, "cost_score" INTEGER, "capacity_score" INTEGER, "compliance_score" REAL, "risk_score" INTEGER, "overall_score" REAL, "score_explanation" TEXT, PRIMARY KEY ("supplier_score_id"), FOREIGN KEY ("supplier_id") REFERENCES "suppliers" ("supplier_id"));
CREATE TABLE "suppliers" ("supplier_id" TEXT, "supplier_name" TEXT, "country" TEXT, PRIMARY KEY ("supplier_id"));
COMMIT;
